package org.apache.commons.codec.binary;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtils_ESTest_test19 extends StringUtils_ESTest_scaffolding {

    /**
     * Decoding four zero bytes as UTF-16BE yields a string of two NUL characters,
     * because UTF-16BE encodes each character using two bytes.
     */
    @Test(timeout = 4000)
    public void newStringUtf16Be_decodesFourZeroBytes_toTwoNulChars() throws Throwable {
        byte[] fourZeroBytes = new byte[4];

        String decoded = StringUtils.newStringUtf16Be(fourZeroBytes);

        // A char[] defaults to '�' (NUL) elements, so this is "��".
        String expectedTwoNulChars = new String(new char[2]);
        assertEquals(expectedTwoNulChars, decoded);
    }
}
